<?php require 'config.php';$errors=[];if(!empty($_SESSION['user_id']))redirect('index.php');if($_SERVER['REQUEST_METHOD']==='POST'){$u=trim($_POST['username']??'');$p=$_POST['password']??'';$user=null;foreach(read_data('users') as $row)if(strcasecmp($row['username'],$u)===0){$user=$row;break;}if(!$user||!password_verify($p,$user['password']))$errors[]='Username atau password salah.';else{session_regenerate_id(true);$_SESSION['user_id']=$user['id'];$_SESSION['username']=$user['username'];redirect('index.php');}}?><!doctype html><html lang="id"><head> <link rel="icon" href="assets/img/logo.png"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/css/style.css"><title>Login</title></head><body><div class="auth-wrapper"><div class="auth-card"><div class="auth-brand"><img src="assets/img/logo.png" alt="Logo" style="height:64px;display:block;margin:0 auto 8px">NetStock</div><h1>Login</h1><?php foreach($errors as $e1):?><div class="alert alert-error"><?=e($e1)?></div><?php endforeach;?><form method="post"><div class="form-group"><label>Username</label><input name="username" required autofocus></div><div class="form-group"><label>Password</label><input type="password" name="password" required></div><button class="btn btn-primary" style="width:100%">Login</button></form><p class="auth-switch">Belum punya akun? <a href="register.php">Daftar</a></p></div></div></body></html>